={{ (() => {
  // Strip /executions/<id> to derive the workflow editor link
  const u = String($('Workflow Error Trigger').item.json.execution?.url || '');
  return u.includes('/executions/') ? u.split('/executions/')[0] : u;
})() }}

={{ (() => {
  // Combine error message + description, redact secret-like tokens, cap at 1000 chars
  const err = $('Workflow Error Trigger').item.json.execution?.error || {};
  const msg = String(err.message || 'Unhandled workflow error');
  const desc = err.description && String(err.description) !== msg ? ' — ' + String(err.description) : '';
  const combined = (msg + desc)
    .replace(/Bearer\s+[A-Za-z0-9._-]+/gi, 'Bearer [REDACTED]')
    .replace(/\b(?:sk-|re_|pat-|xox[bp]-|n8n_api_)[A-Za-z0-9_-]+/g, '[REDACTED]')
    .replace(/\beyJ[A-Za-z0-9_-]{15,}\.[A-Za-z0-9._-]+/g, '[REDACTED_JWT]');
  return combined.slice(0, 1000);
})() }}

={{ (() => {
  const ts = $('Workflow Error Trigger').item.json.execution?.error?.timestamp;
  return ts ? DateTime.fromMillis(Number(ts)).toUTC().toISO() : DateTime.now().toUTC().toISO();
})() }}

={{ (() => {
  // Best-effort extraction of submission_id when present in error payload
  const raw = JSON.stringify($('Workflow Error Trigger').item.json.execution?.error || {});
  const match = raw.match(/\bsub_[a-zA-Z0-9_-]{4,64}\b/);
  return match ? match[0] : '';
})() }}

parameters.blocksUi:
={{ (() => {
  // Build Slack Block Kit admin error alert with workflow + execution links and DB persistence status
  const ctx = $('Normalize Error Context').item.json;
  const dbRes = $('Prepare Admin Alert').item.json || {};
  const dbId = dbRes.id && !dbRes.error ? String(dbRes.id) : null;
  const dbStatus = dbId
    ? 'Recorded (ID: `' + dbId + '`)'
    : '⚠️ Failed to write to Supabase workflow_errors';
  const headerText = ('🚨 [WORKFLOW ERROR] ' + ctx.workflow_name).slice(0, 150);
  const fields = [
    { type: 'mrkdwn', text: '*Workflow:*\n' + ctx.workflow_name + (ctx.workflow_id ? ' (`' + ctx.workflow_id + '`)' : '') },
    { type: 'mrkdwn', text: '*Failed Node:*\n`' + ctx.node_name + '`' },
    { type: 'mrkdwn', text: '*Execution ID:*\n`' + (ctx.execution_id || 'n/a') + '`' },
    { type: 'mrkdwn', text: '*Timestamp (UTC):*\n' + ctx.error_timestamp },
    { type: 'mrkdwn', text: '*Supabase Log:*\n' + dbStatus },
  ];
  if (ctx.submission_id) {
    fields.push({ type: 'mrkdwn', text: '*Submission ID:*\n`' + ctx.submission_id + '`' });
  }
  const links = [];
  if (ctx.execution_url) links.push('<' + ctx.execution_url + '|Open Failed Execution>');
  if (ctx.workflow_url) links.push('<' + ctx.workflow_url + '|Open Workflow Editor>');
  links.push('<http://localhost:5173/dashboard|Open LeadFlow Dashboard>');

  return {
    blocks: [
      {
        type: 'header',
        text: { type: 'plain_text', text: headerText, emoji: true },
      },
      {
        type: 'section',
        fields,
      },
      {
        type: 'section',
        text: {
          type: 'mrkdwn',
          text: '*Error Message:*\n```' + String(ctx.error_message || '').slice(0, 900) + '```',
        },
      },
      { type: 'divider' },
      {
        type: 'section',
        text: {
          type: 'mrkdwn',
          text: '🔧 *Quick Links:* ' + links.join('  |  '),
        },
      },
      {
        type: 'context',
        elements: [
          {
            type: 'mrkdwn',
            text: 'WF04 Error Handler | Safe retry protected by submission_id, email idempotency_key & HubSpot email upsert.',
          },
        ],
      },
    ],
  };
})() }}
